import type { Locale } from "./locale";

type Row = readonly [zh: string, en: string, ja: string, ko: string];

function pack(rows: Record<string, Row>): Record<Locale, Record<string, string>> {
  const out: Record<Locale, Record<string, string>> = { zh: {}, en: {}, ja: {}, ko: {} };
  for (const [key, [zh, en, ja, ko]] of Object.entries(rows)) {
    out.zh[key] = zh;
    out.en[key] = en;
    out.ja[key] = ja;
    out.ko[key] = ko;
  }
  return out;
}

